select public.svc_sync_tenant('{"slug":"jh-auto-detailing","name":"JH Auto Detailing","shortName":"JH Detailing","kind":"detailing","tagline":"Čištění interiéru, leštění laku, keramika, PPF a tónování oken v Tišnově","description":"Jsme detailingové studio v Tišnově. Postaráme se o interiér od základního vysátí až po tepování sedaček, vyleštíme lak a ochráníme ho voskem nebo keramikou. Lepíme PPF fólie a tónujeme okna s atestem. Termín si zarezervujete online během minuty – bez registrace.","locale":"cs-CZ","timezone":"Europe/Prague","currency":"CZK","accentColor":"#E1251B","contacts":{"phone":"+420777056596","address":"Olbrachtova 1740, 666 03 Tišnov","legalAddress":"Květnická 1621, 666 01 Tišnov","mapUrl":"https://www.google.com/maps/search/?api=1&query=Olbrachtova%201740%2C%20666%2003%20Ti%C5%A1nov"},"images":{"hero":"/s/jh-auto-detailing/media/hero.webp","logo":"/s/jh-auto-detailing/media/logo.png"},"hours":{"mon":[["08:00","17:00"]],"tue":[["08:00","17:00"]],"wed":[["08:00","17:00"]],"thu":[["08:00","17:00"]],"fri":[["08:00","17:00"]],"sat":[],"sun":[]},"closedDates":["2026-10-28","2026-11-17","2026-12-24","2026-12-25","2026-12-26","2027-01-01","2027-03-26","2027-03-29","2027-05-01","2027-05-08","2027-07-05","2027-07-06","2027-09-28","2027-10-28","2027-11-17","2027-12-24","2027-12-25","2027-12-26"],"booking":{"slotStepMinutes":30,"minLeadMinutes":120,"horizonDays":45,"cancelCutoffHours":24,"defaultBufferMinutes":30},"resources":[{"key":"box-1","name":"Box 1"}],"services":[{"key":"interier-1","name":"Interiér 1: Základní čištění","description":"Vysátí interiéru a kufru, utření prachu, provonění.","category":"Interiér","price":1600,"priceFrom":true,"durationMinutes":90,"resources":["box-1"]},{"key":"interier-2","name":"Interiér 2: Detailní údržba","description":"Vše ze základního čištění a navíc komplexní čištění, okna zevnitř, čištění mezidveřních prostor a impregnace plastů.","category":"Interiér","price":2700,"priceFrom":true,"durationMinutes":180,"resources":["box-1"]},{"key":"interier-3","name":"Interiér 3: Čištění a tepování","description":"Vše z detailní údržby a navíc tepování sedaček a tepování kufru.","category":"Interiér","price":3600,"priceFrom":true,"durationMinutes":360,"resources":["box-1"]},{"key":"lesteni-bronz","name":"Leštění laku Bronz","description":"Vydrží týdny. Detailní mytí a dekontaminace laku, jednostupňové leštění (odstraní 60–70 % škrábanců), ochrana detailerem na 4–8 týdnů.","category":"Leštění laku","price":7000,"priceFrom":true,"durationMinutes":480,"resources":["box-1"]},{"key":"lesteni-silver","name":"Leštění laku Silver","description":"Vydrží měsíce. Detailní mytí a dekontaminace laku, dvoustupňové leštění (70–80 % škrábanců), ochrana syntetickým voskem na 6 měsíců, leštění světlometů, impregnace pneumatik a plastů.","category":"Leštění laku","price":10000,"priceFrom":true,"durationMinutes":1440,"resources":["box-1"]},{"key":"lesteni-gold","name":"Leštění laku Gold","description":"Vydrží až 5 let. Detailní mytí a dekontaminace laku, dvou- až třístupňové leštění (80–95 % škrábanců), keramická ochrana až na 5 let, leštění světlometů, impregnace pneumatik a plastů.","category":"Leštění laku","price":12000,"priceFrom":true,"durationMinutes":2880,"resources":["box-1"]},{"key":"ochrana-detailer","name":"Detailer: rychlé osvěžení laku","description":"Rychlé osvěžení vzhledu laku a ochrana na týdny.","category":"Ochrana laku","price":3000,"priceFrom":true,"durationMinutes":180,"resources":["box-1"]},{"key":"ochrana-vosk","name":"Syntetický vosk","description":"Lesk a ochrana laku na měsíce.","category":"Ochrana laku","price":4000,"priceFrom":true,"durationMinutes":240,"resources":["box-1"]},{"key":"ochrana-keramika","name":"Keramická ochrana laku","description":"Keramický povlak, který vydrží až 5 let. Varianty na 1, 3 nebo 5 let.","category":"Ochrana laku","price":5000,"priceFrom":true,"durationMinutes":1440,"resources":["box-1"]},{"key":"ppf-dily","name":"PPF fólie na díly vozu","description":"O