m a kartičkou o aplikaci – legálně na STK."},{"icon":"clock","title":"Rezervace online","text":"Termín si vyberete sami, bez registrace a bez čekání na telefonu."}],"gallery":[{"image":"/s/jh-auto-detailing/media/work-g1-after.webp","before":"/s/jh-auto-detailing/media/work-g1-before.webp","caption":"Kompletní čištění interiéru, Ford Focus"},{"image":"/s/jh-auto-detailing/media/work-dacia-duster-after.webp","before":"/s/jh-auto-detailing/media/work-dacia-duster-before.webp","caption":"Čištění interiéru, Dacia Duster"},{"image":"/s/jh-auto-detailing/media/work-g7-after.webp","before":"/s/jh-auto-detailing/media/work-g7-before.webp","caption":"Tepování koberců, Porsche Cayenne GTS"},{"image":"/s/jh-auto-detailing/media/work-g8-after.webp","before":"/s/jh-auto-detailing/media/work-g8-before.webp","caption":"Tepování kufru"},{"image":"/s/jh-auto-detailing/media/work-g2-after.webp","before":"/s/jh-auto-detailing/media/work-g2-before.webp","caption":"Čištění sedaček a interiéru"},{"image":"/s/jh-auto-detailing/media/work-g9-after.webp","before":"/s/jh-auto-detailing/media/work-g9-before.webp","caption":"Čištění výplně dveří"},{"image":"/s/jh-auto-detailing/media/work-porsche-interior.webp","caption":"Interiér po čištění, Porsche"}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, '3bb93e09d25c66d230971a14031794f65a461b1014e141f3b8cb65ecc5ec32fc', true);
